import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useParams, useLocation } from 'react-router-dom';
import io from 'socket.io-client';
import { Avatar3D } from '../components/Avatar3D';
import { DraggableUserVideo } from '../components/DraggableUserVideo';
import { ShareModal } from '../components/ShareModal';
import { VideoPlayerModal } from '../components/VideoPlayerModal';
import { SidePanel } from '../components/SidePanel';
import { CallControls } from '../components/CallControls';
import { useVoiceInput } from '../hooks/useVoiceInput';
import { sendChatMessage, getSessionMessages } from '../utils/api';
import toast, { Toaster } from 'react-hot-toast';

const socket = io('http://localhost:8000', {
  transports: ['websocket'],
  reconnection: true,
  reconnectionAttempts: 5,
  reconnectionDelay: 1000,
});

const cleanTextForSpeech = (text) => {
  if (!text) return '';
  return text
    .replace(/[\u{1F300}-\u{1F9FF}]|[\u{2600}-\u{26FF}]|[\u{2700}-\u{27BF}]/gu, '')
    .replace(/[👋👍❤️🎉😂🔥💪✨🌟💯🎯🎊🎈🎨📝💬👥😊😄]/g, '')
    .replace(/\*\*/g, '').replace(/\*/g, '').replace(/__/g, '').replace(/_/g, '')
    .replace(/#+\s/g, '').replace(/^\s*[-•]\s/gm, '').replace(/^\s*\d+\.\s/gm, '')
    .replace(/\s+/g, ' ').trim();
};

let CACHED_MALE_VOICE = null;
let CACHED_FEMALE_VOICE = null;

const initializeVoices = () => {
  const voices = window.speechSynthesis.getVoices();
  if (!voices || voices.length === 0) return;
  
  if (!CACHED_MALE_VOICE) {
    CACHED_MALE_VOICE = 
      voices.find(v => v.lang === 'en-IN' && v.name.includes('Male')) ||
      voices.find(v => v.lang === 'en-IN') ||
      voices.find(v => v.name.includes('Ravi')) ||
      voices.find(v => v.name.includes('Indian')) ||
      voices.find(v => v.lang === 'en-US' && !v.name.includes('Female')) ||
      voices[0];
    console.log('🎤 MALE VOICE:', CACHED_MALE_VOICE?.name);
  }
  
  if (!CACHED_FEMALE_VOICE) {
    CACHED_FEMALE_VOICE = 
      voices.find(v => v.lang === 'en-IN' && v.name.includes('Female')) ||
      voices.find(v => v.lang === 'en-IN' && v.name.includes('Lekha')) ||
      voices.find(v => v.name.includes('Indian') && v.name.includes('Female')) ||
      voices.find(v => v.lang === 'en-US' && v.name.includes('Female')) ||
      (voices.length > 1 ? voices[1] : voices[0]);
    console.log('🎤 FEMALE VOICE:', CACHED_FEMALE_VOICE?.name);
  }
};

export const VideoCallPage = ({ companion, onEndCall }) => {
  const { roomId } = useParams();
  const location = useLocation();
  const [userId, setUserId] = useState('');
  const [userName, setUserName] = useState('User');
  const [isMuted, setIsMuted] = useState(false);
  const [isVideoOff, setIsVideoOff] = useState(false);
  const [mediaStream, setMediaStream] = useState(null);
  const [isCameraLoading, setIsCameraLoading] = useState(true);
  const [callTime, setCallTime] = useState(0);
  const [isShareModalOpen, setShareModalOpen] = useState(false);
  const [activePanel, setActivePanel] = useState('chat');
  const [isMenuOpen, setMenuOpen] = useState(false);
  const [reactions, setReactions] = useState([]);
  const [playingVideoId, setPlayingVideoId] = useState(null);
  const [messages, setMessages] = useState([]);
  const [isAISpeaking, setIsAISpeaking] = useState(false);
  const [currentSpeakingText, setCurrentSpeakingText] = useState('');
  const [hasPlayedIntro, setHasPlayedIntro] = useState(location.state?.resuming || false);
  const [customAnimation, setCustomAnimation] = useState(null);
  const [participants, setParticipants] = useState([]);
  const [remoteStreams, setRemoteStreams] = useState({});
  const [tutorId, setTutorId] = useState('omkar_ai');
  const [subject, setSubject] = useState('AI & ML');

  const peerConnections = useRef({});
  const hasJoinedRoom = useRef(false);
  const userVideoRef = useRef(null);
  const synth = useRef(null);
  const mediaStreamRef = useRef(null);
  const timerRef = useRef(null);
  const currentUtteranceRef = useRef(null);
  const isCurrentlySpeakingRef = useRef(false);

  useEffect(() => {
    const initializeSession = async () => {
      const userStr = localStorage.getItem('currentUser');
      if (userStr) {
        const userData = JSON.parse(userStr);
        setUserId(userData.email || `user_${Date.now()}`);
        setUserName(userData.name || userData.email?.split('@')[0] || 'User');
      } else {
        setUserId(`guest_${Date.now()}`);
        setUserName('Guest');
      }

      const routeTutorId = location.state?.tutorId || companion?.id || 'omkar_ai';
      const routeSubject = location.state?.subject || companion?.subject || 'AI & ML';
      const isResuming = location.state?.resuming || false;

      console.log('📋 TutorId:', routeTutorId, 'Subject:', routeSubject);

      setTutorId(routeTutorId);
      setSubject(routeSubject);

      if (isResuming && roomId) {
        try {
          const oldMessages = await getSessionMessages(roomId);
          if (oldMessages && oldMessages.length > 0) {
            const formattedMessages = oldMessages.map(msg => ({
              id: Date.now() + Math.random(),
              text: msg.content,
              sender: msg.role === 'user' ? 'user' : 'ai',
              timestamp: new Date(msg.timestamp)
            }));
            setMessages(formattedMessages);
            setHasPlayedIntro(true);
          }
        } catch (error) {
          console.error('❌ Error loading messages:', error);
        }
      }
    };

    initializeSession();
  }, [roomId, location.state, companion]);

  const getCompanionId = useCallback(() => {
    return tutorId || companion?.id || 'omkar_ai';
  }, [companion, tutorId]);

  const handlePlayAnimation = useCallback((animationId) => {
    setCustomAnimation(animationId);
    setTimeout(() => setCustomAnimation(null), 10000);
  }, []);

  const handleStopAI = useCallback(() => {
    isCurrentlySpeakingRef.current = false;
    window.speechSynthesis.cancel();
    if (currentUtteranceRef.current) currentUtteranceRef.current = null;
    setIsAISpeaking(false);
    setCurrentSpeakingText('');
  }, []);

  const speakWithCorrectVoice = useCallback((text, isFemale) => {
    return new Promise((resolve, reject) => {
      const cleanedText = cleanTextForSpeech(text);
      if (!cleanedText) {
        resolve();
        return;
      }

      window.speechSynthesis.cancel();
      
      const utterance = new SpeechSynthesisUtterance(cleanedText);
      const selectedVoice = isFemale ? CACHED_FEMALE_VOICE : CACHED_MALE_VOICE;
      
      if (selectedVoice) {
        utterance.voice = selectedVoice;
        utterance.lang = selectedVoice.lang;
      } else {
        utterance.lang = 'en-IN';
      }
      
      utterance.rate = 1.1; // ✅ Slightly faster for natural speech
      utterance.pitch = 1.0;
      utterance.volume = 1.0;

      utterance.onstart = () => {
        isCurrentlySpeakingRef.current = true;
        setIsAISpeaking(true);
        setCurrentSpeakingText(cleanedText);
      };

      utterance.onend = () => {
        isCurrentlySpeakingRef.current = false;
        setIsAISpeaking(false);
        setCurrentSpeakingText('');
        currentUtteranceRef.current = null;
        resolve();
      };

      utterance.onerror = (err) => {
        isCurrentlySpeakingRef.current = false;
        setIsAISpeaking(false);
        setCurrentSpeakingText('');
        currentUtteranceRef.current = null;
        reject(err);
      };

      currentUtteranceRef.current = utterance;
      window.speechSynthesis.speak(utterance);
    });
  }, []);

  const playAudio = useCallback(async (audioUrl, fullText) => {
    try {
      if (isCurrentlySpeakingRef.current) {
        handleStopAI();
        await new Promise(resolve => setTimeout(resolve, 100));
      }

      const isFemale = getCompanionId() === 'priya_biology';
      isCurrentlySpeakingRef.current = true;
      await speakWithCorrectVoice(fullText, isFemale);
    } catch (error) {
      console.error('❌ TTS error:', error);
      isCurrentlySpeakingRef.current = false;
      setIsAISpeaking(false);
      setCurrentSpeakingText('');
    }
  }, [getCompanionId, handleStopAI, speakWithCorrectVoice]);

  const getMedia = useCallback(async (opts = { video: true, audio: true }) => {
    setIsCameraLoading(true);
    try {
      const stream = await navigator.mediaDevices.getUserMedia(opts);
      setMediaStream(stream);
      mediaStreamRef.current = stream;

      if (userVideoRef.current && !isVideoOff) {
        userVideoRef.current.srcObject = stream;
        userVideoRef.current.play().catch(() => {});
      }

      return stream;
    } catch (err) {
      console.error('❌ Camera error:', err);
      if (err.name === 'NotAllowedError') {
        toast.error('Please allow camera/microphone access');
      }
      return null;
    } finally {
      setIsCameraLoading(false);
    }
  }, [isVideoOff]);

  const createPeerConnection = useCallback((targetUserId, stream) => {
    const pc = new RTCPeerConnection({
      iceServers: [
        { urls: 'stun:stun.l.google.com:19302' },
        { urls: 'turn:openrelay.metered.ca:80', username: 'openrelayproject', credential: 'openrelayproject' }
      ]
    });

    peerConnections.current[targetUserId] = pc;

    if (stream) {
      stream.getTracks().forEach((track) => pc.addTrack(track, stream));
    }

    pc.ontrack = (event) => {
      setRemoteStreams((prev) => ({ ...prev, [targetUserId]: event.streams[0] }));
    };

    pc.onicecandidate = (event) => {
      if (event.candidate) {
        socket.emit('ice-candidate', { roomId, candidate: event.candidate, targetUserId, fromUserId: userId });
      }
    };

    return pc;
  }, [roomId, userId]);

  useEffect(() => {
    initializeVoices();
    window.speechSynthesis.onvoiceschanged = initializeVoices;
    setTimeout(initializeVoices, 100);
    setTimeout(initializeVoices, 500);
  }, []);

  useEffect(() => {
    let mounted = true;

    const initWebRTC = async () => {
      const stream = await getMedia({ video: true, audio: true });
      if (!stream || !mounted) return;

      await new Promise(resolve => setTimeout(resolve, 300));

      if (!hasJoinedRoom.current) {
        hasJoinedRoom.current = true;
        socket.emit('join-room', { roomId, userId, userName, companionId: companion?.id });
      }

      socket.on('user-joined', (data) => {
        const displayName = data.userName || data.userId.substring(0, 15);
        toast.success(`${displayName}... joined`, { duration: 2000, icon: '👋' });
        setParticipants((prev) => {
          if (prev.some(p => p.userId === data.userId)) return prev;
          return [...prev, { userId: data.userId, userName: data.userName || data.userId, joinedAt: Date.now() }];
        });

        const pc = createPeerConnection(data.userId, stream);
        pc.createOffer()
          .then((offer) => pc.setLocalDescription(offer))
          .then(() => {
            socket.emit('offer', { roomId, offer: pc.localDescription, targetUserId: data.userId, fromUserId: userId });
          });
      });

      socket.on('existing-users', (users) => {
        setParticipants(users.map(u => ({ userId: u.userId || u, userName: u.userName || u.userId || u, joinedAt: Date.now() })));
      });

      socket.on('user-left', (data) => {
        setParticipants((prev) => prev.filter((p) => p.userId !== data.userId));
        setRemoteStreams((prev) => {
          const newStreams = { ...prev };
          delete newStreams[data.userId];
          return newStreams;
        });
        if (peerConnections.current[data.userId]) {
          peerConnections.current[data.userId].close();
          delete peerConnections.current[data.userId];
        }
      });

      socket.on('offer', async (data) => {
        const { offer, fromUserId } = data;
        const pc = createPeerConnection(fromUserId, stream);
        await pc.setRemoteDescription(new RTCSessionDescription(offer));
        const answer = await pc.createAnswer();
        await pc.setLocalDescription(answer);
        socket.emit('answer', { roomId, answer, targetUserId: fromUserId, fromUserId: userId });
      });

      socket.on('answer', async (data) => {
        const { answer, fromUserId } = data;
        const pc = peerConnections.current[fromUserId];
        if (pc && pc.signalingState === 'have-local-offer') {
          await pc.setRemoteDescription(new RTCSessionDescription(answer));
        }
      });

      socket.on('ice-candidate', async (data) => {
        const { candidate, fromUserId } = data;
        const pc = peerConnections.current[fromUserId];
        if (pc && pc.remoteDescription) {
          try {
            await pc.addIceCandidate(new RTCIceCandidate(candidate));
          } catch (err) {
            console.error('ICE error:', err);
          }
        }
      });

      socket.on('chat-message', (data) => {
        const newMessage = { sender: data.sender, text: data.message, timestamp: data.timestamp, userId: data.userId };
        setMessages((prev) => {
          if (prev.some(m => m.timestamp === data.timestamp && m.userId === data.userId)) return prev;
          return [...prev, newMessage];
        });
      });
    };

    initWebRTC();

    if (window.Tone) {
      try { synth.current = new window.Tone.PolySynth().toDestination(); } catch (e) {}
    }

    timerRef.current = setInterval(() => setCallTime((t) => t + 1), 1000);

    return () => {
      mounted = false;
      hasJoinedRoom.current = false;
      clearInterval(timerRef.current);
      if (mediaStreamRef.current) mediaStreamRef.current.getTracks().forEach((t) => t.stop());
      window.speechSynthesis.cancel();
      Object.values(peerConnections.current).forEach((pc) => { try { pc.close(); } catch (e) {} });
      socket.emit('leave-room', { roomId, userId });
      socket.off('user-joined');
      socket.off('user-left');
      socket.off('existing-users');
      socket.off('offer');
      socket.off('answer');
      socket.off('ice-candidate');
      socket.off('chat-message');
    };
  }, [roomId, userId, userName, companion?.id, getMedia, createPeerConnection]);

  useEffect(() => {
    mediaStreamRef.current = mediaStream;
    if (userVideoRef.current && mediaStream) {
      userVideoRef.current.srcObject = mediaStream;
      userVideoRef.current.play().catch(() => {});
    }
  }, [mediaStream]);

  useEffect(() => {
    if (!mediaStream) return;
    mediaStream.getAudioTracks().forEach((track) => { track.enabled = !isMuted; });
    mediaStream.getVideoTracks().forEach((track) => { track.enabled = !isVideoOff; });
  }, [isMuted, isVideoOff, mediaStream]);

  const sendReaction = (emoji) => {
    if (synth.current) {
      const notes = { '👍': 'C4', '❤️': 'E4', '🎉': 'G4', '😂': 'A4' };
      try { synth.current.triggerAttackRelease(notes[emoji] || 'C5', '8n'); } catch (e) {}
    }
    const newReaction = { id: Date.now(), emoji, left: Math.random() * 80 + 10 };
    setReactions((prev) => [...prev, newReaction]);
    setTimeout(() => setReactions((prev) => prev.filter((r) => r.id !== newReaction.id)), 4000);
  };

  const handleIntroComplete = useCallback(async (introData) => {
    console.log('🎬 handleIntroComplete called for:', tutorId, 'hasPlayedIntro:', hasPlayedIntro, 'messagesLength:', messages.length);
    
    if (messages.length > 0 || hasPlayedIntro) {
      console.log('❌ Intro blocked - already played');
      return;
    }

    if (introData) {
      console.log('✅ Playing intro NOW');
      setHasPlayedIntro(true);

      const introMsg = {
        sender: 'ai',
        text: introData.message,
        timestamp: new Date().toISOString(),
        source: 'intro',
        id: Date.now()
      };

      setMessages([introMsg]);
      await playAudio(null, introData.message);
    }
  }, [hasPlayedIntro, playAudio, messages.length, tutorId]);

  const handleVoiceResult = useCallback(async (transcript) => {
    if (!transcript?.trim()) return;

    const userMessage = { sender: 'user', text: transcript, timestamp: new Date().toISOString(), userId: userId };
    setMessages((prev) => [...prev, userMessage]);

    socket.emit('chat-message', { roomId, userId, message: transcript, sender: 'user', timestamp: userMessage.timestamp });

    try {
      const chatHistory = messages.slice(-10).map(m => ({ role: m.sender === 'user' ? 'user' : 'assistant', content: m.text }));
      const response = await sendChatMessage(transcript, getCompanionId(), roomId, subject, 0, chatHistory);

      const aiTimestamp = new Date().toISOString();
      const aiMessage = {
        sender: 'ai',
        text: response.text || response.message || 'I received your message.',
        timestamp: aiTimestamp,
        source: response.source || 'gemini',
        userId: getCompanionId(),
      };

      setMessages((prev) => [...prev, aiMessage]);
      socket.emit('chat-message', { roomId, userId: getCompanionId(), message: aiMessage.text, sender: 'ai', timestamp: aiTimestamp });
      await playAudio(response.audioUrl, aiMessage.text);
    } catch (error) {
      console.error('Error in voice chat:', error);
    }
  }, [roomId, playAudio, userId, messages, getCompanionId, subject]);

  const { isListening, startListening, stopListening } = useVoiceInput({
    onResult: handleVoiceResult,
    language: 'en-US',
  });

  const handleSendMessage = async (text) => {
    if (!text?.trim()) return;

    const timestamp = new Date().toISOString();
    const userMessage = { sender: 'user', text, timestamp, userId: userId };
    setMessages((prev) => [...prev, userMessage]);

    socket.emit('chat-message', { roomId, userId, message: text, sender: 'user', timestamp });

    try {
      const chatHistory = messages.slice(-10).map(m => ({ role: m.sender === 'user' ? 'user' : 'assistant', content: m.text }));
      const response = await sendChatMessage(text, getCompanionId(), roomId, subject, 0, chatHistory);

      const aiTimestamp = new Date().toISOString();
      const aiMessage = {
        sender: 'ai',
        text: response.text || response.message || 'I received your message.',
        timestamp: aiTimestamp,
        source: response.source || 'gemini',
        userId: getCompanionId(),
      };

      setMessages((prev) => [...prev, aiMessage]);
      socket.emit('chat-message', { roomId, userId: getCompanionId(), message: aiMessage.text, sender: 'ai', timestamp: aiTimestamp });
      await playAudio(response.audioUrl, aiMessage.text);
    } catch (error) {
      console.error('Error sending message:', error);
    }
  };

  const formatTime = (seconds) =>
    `${Math.floor(seconds / 60).toString().padStart(2, '0')}:${(seconds % 60).toString().padStart(2, '0')}`;

  return (
    <>
      <Toaster position="top-center" />
      
      <div className="relative w-full h-screen bg-gradient-to-br from-gray-900 via-purple-900 to-indigo-900 overflow-hidden flex">
        <div className="flex-1 relative flex items-center justify-center">
          <Avatar3D
            avatarMode={customAnimation || (isAISpeaking ? 'talk' : 'idle')}
            companionId={tutorId}
            isAISpeaking={isAISpeaking}
            currentText={currentSpeakingText}
            onIntroComplete={handleIntroComplete}
            skipIntro={hasPlayedIntro || messages.length > 0}
          />

          <div className="absolute top-4 left-4 bg-black/50 backdrop-blur-sm px-4 py-2 rounded-lg text-white flex items-center gap-2 z-10">
            <span className="w-2 h-2 bg-red-500 rounded-full animate-pulse"></span>
            <span className="font-mono">{formatTime(callTime)}</span>
          </div>

          <div className="absolute top-4 right-4 z-10">
            <button onClick={() => setMenuOpen(!isMenuOpen)} className="p-3 bg-gray-800/80 backdrop-blur-sm rounded-full hover:bg-gray-700 transition-colors">
              <svg className="w-6 h-6 text-white" fill="currentColor" viewBox="0 0 20 20">
                <circle cx="10" cy="5" r="1.5"/>
                <circle cx="10" cy="10" r="1.5"/>
                <circle cx="10" cy="15" r="1.5"/>
              </svg>
            </button>

            {isMenuOpen && (
              <div className="absolute right-0 top-full mt-2 w-56 bg-gray-800 rounded-lg shadow-2xl border border-gray-700 py-2">
                <button onClick={() => { setActivePanel('chat'); setMenuOpen(false); }} className={`w-full px-4 py-2 text-left transition-colors ${activePanel === 'chat' ? 'bg-blue-600 text-white' : 'text-gray-300 hover:bg-gray-700'}`}>💬 Chat</button>
                <button onClick={() => { setActivePanel('notes'); setMenuOpen(false); }} className={`w-full px-4 py-2 text-left transition-colors ${activePanel === 'notes' ? 'bg-blue-600 text-white' : 'text-gray-300 hover:bg-gray-700'}`}>📝 Notes</button>
                <button onClick={() => { setActivePanel('whiteboard'); setMenuOpen(false); }} className={`w-full px-4 py-2 text-left transition-colors ${activePanel === 'whiteboard' ? 'bg-blue-600 text-white' : 'text-gray-300 hover:bg-gray-700'}`}>🎨 Whiteboard</button>
                <div className="my-2 border-t border-gray-700"></div>
                <div className="px-2 py-1 text-xs text-gray-500 uppercase">Avatar Actions</div>
                <button onClick={() => { handlePlayAnimation('walk'); setMenuOpen(false); }} className="w-full px-4 py-2 text-left text-gray-300 hover:bg-gray-700 text-sm">🏃 Walk</button>
                <button onClick={() => { handlePlayAnimation('dance'); setMenuOpen(false); }} className="w-full px-4 py-2 text-left text-gray-300 hover:bg-gray-700 text-sm">💃 Dance</button>
                <button onClick={() => { handlePlayAnimation('wave'); setMenuOpen(false); }} className="w-full px-4 py-2 text-left text-gray-300 hover:bg-gray-700 text-sm">👋 Wave</button>
              </div>
            )}
          </div>

          <DraggableUserVideo videoRef={userVideoRef} userId={userName} isMuted={isMuted} isVideoOff={isVideoOff} isCameraLoading={isCameraLoading} />

          {Object.entries(remoteStreams).map(([remoteUserId, stream], index) => {
            const participant = participants.find(p => p.userId === remoteUserId);
            return <RemoteUserVideo key={remoteUserId} stream={stream} userId={participant?.userName || remoteUserId} index={index} />;
          })}

          {reactions.map((r) => (
            <div key={r.id} className="absolute bottom-32 text-4xl animate-bounce-up pointer-events-none z-10" style={{ left: `${r.left}%` }}>{r.emoji}</div>
          ))}

          <div className="absolute bottom-6 left-1/2 transform -translate-x-1/2 z-20">
            <CallControls isMuted={isMuted} setIsMuted={setIsMuted} isVideoOff={isVideoOff} setIsVideoOff={setIsVideoOff} sendReaction={sendReaction} onEndCall={onEndCall} />
          </div>
        </div>

        <div className="w-[30%] border-l border-gray-700 bg-gray-900">
          <SidePanel
            activePanel={activePanel}
            setActivePanel={setActivePanel}
            messages={messages}
            onSendMessage={handleSendMessage}
            roomId={roomId}
            companion={{ id: tutorId, name: tutorId === 'omkar_ai' ? 'Omkar' : 'Priya', subject }}
            userId={userId}
            onStopAI={handleStopAI}
            startListening={startListening}
            stopListening={stopListening}
            isListening={isListening}
            participants={[
              { userId: tutorId === 'omkar_ai' ? 'Omkar' : 'Priya', role: 'AI', isOnline: true },
              { userId: userName, role: 'You (Host)', isOnline: true },
              ...participants.map(p => ({ userId: p.userName || p.userId.substring(0, 12) + '...', role: 'Participant', isOnline: true }))
            ]}
          />
        </div>
      </div>

      {isShareModalOpen && <ShareModal roomId={roomId} onClose={() => setShareModalOpen(false)} />}
      {playingVideoId && <VideoPlayerModal videoId={playingVideoId} onClose={() => setPlayingVideoId(null)} />}
    </>
  );
};

const RemoteUserVideo = ({ stream, userId, index }) => {
  const videoRef = useRef(null);
  const audioRef = useRef(null);

  useEffect(() => {
    if (videoRef.current && stream) {
      videoRef.current.srcObject = stream;
      videoRef.current.play().catch(() => {});
    }
    if (audioRef.current && stream) {
      audioRef.current.srcObject = stream;
      audioRef.current.play().catch(() => {});
    }
  }, [stream]);

  return (
    <div className="absolute w-48 h-36 bg-black rounded-lg overflow-hidden border-2 border-blue-500 shadow-2xl z-10" style={{ bottom: `${140 + index * 160}px`, right: '20px' }}>
      <video ref={videoRef} autoPlay playsInline className="w-full h-full object-cover" />
      <audio ref={audioRef} autoPlay />
      <div className="absolute bottom-2 left-2 bg-black/70 px-2 py-1 rounded text-xs text-white">
        {userId.length > 12 ? userId.substring(0, 12) + '...' : userId}
      </div>
    </div>
  );
};
